using System.Linq;using System.Data.Entity;using System.Web.Mvc;using MaSV_LTW_MyStore.Models; namespace MaSV_LTW_MyStore.Areas.Admin.Controllers { public class OrdersController:Controller { StoreContext db=new StoreContext(); protected override void OnActionExecuting(ActionExecutingContext c){if(Session["Role"]==null||Session["Role"].ToString()!="A"){c.Result=RedirectToAction("Login","Account",new{area=""});return;}base.OnActionExecuting(c);} public ActionResult Index(){return View(db.Orders.Include(o=>o.Customer).OrderByDescending(o=>o.OrderDate).ToList());} } }